import { Component, For, onCleanup, onMount, ParentComponent, Show, useContext } from "solid-js";

import ActionHandler from "#core/ui/input/action-handler.js";
import { Activatable } from "#core/ui-next/components/activatable.jsx";
import { CardFrame } from "#core/ui-next/components/card-frame.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { HSlot, VSlot } from "#core/ui-next/components/slot.jsx";
import { Tooltip, TooltipHorizontalPosition, TooltipVerticalPosition } from "#core/ui-next/components/tooltip.jsx";
import { HotkeyContext } from "#core/ui-next/services/hotkey.js";
import { LayoutModel } from "#core/ui-next/utilities/layout-utilities.js";

import {
	MilitaryStructureDetail,
	useVictoriesScreenContext,
	VictoryTabType,
} from "#base/ui-next/screens/victories/victories-screen-model.js";
import { VictoryHeader, VictoryRow, VictoryTabBase } from "#base/ui-next/screens/victories/victory-tab-base.jsx";

const SAME_IDEOLOGY_TINT = "#FFFFFF";
const RIVAL_IDEOLOGY_TINT = "#FF9047";

const MilitaryTooltip: ParentComponent<MilitaryStructureDetail> = (props) => {
	return (
		<Tooltip
			initialHPosition={TooltipHorizontalPosition.RIGHT}
			initialVPosition={TooltipVerticalPosition.CENTER}
		>
			<Tooltip.Trigger>{props.children}</Tooltip.Trigger>
			<Tooltip.Content>
				<Tooltip.Frame>
					<div class="items-center">
						<div class="font-title-base fxs-header uppercase self-center mb-4">
							<L10n.Compose text={props.hasMet ? props.name : "LOC_LEADER_UNMET_NAME"} />
						</div>
						<CardFrame class="mb-4">
							<For each={props.breakdown}>
								{(breakdown) => (
									<HSlot class="mx-3 my-2 justify-between font-body text-sm text-white ml-4">
										<div>
											<L10n.Compose text={breakdown.name} />
										</div>
										<div class="ml-8">{Locale.toNumber(breakdown.points)}</div>
									</HSlot>
								)}
							</For>
						</CardFrame>
						<Show when={props.breakdown.length > 1}>
							<CardFrame>
								<HSlot class="mx-3 my-2 justify-between">
									<div class="font-title-sm uppercase fxs-header">
										<L10n.Compose text="LOC_VICTORIES_TOOLTIP_TOTAL" />
									</div>
									<div class="ml-12 font-body text-sm text-white">
										{Locale.toNumber(props.points)}
									</div>
								</HSlot>
							</CardFrame>
						</Show>
					</div>
				</Tooltip.Frame>
			</Tooltip.Content>
		</Tooltip>
	);
};

export const MilitaryVictoryTab: Component = () => {
	const model = useVictoriesScreenContext();
	const layoutModel = LayoutModel.get();

	const onMilitaryFocus = (playerId: PlayerId) => {
		model.focusPlayer(playerId, VictoryTabType.Military);
	};

	const onMilitaryBlur = (playerId: PlayerId) => {
		model.unFocusPlayer(playerId, VictoryTabType.Military);
	};

	const hotkeyContext = useContext(HotkeyContext);

	onMount(() => {
		hotkeyContext.registerNavtray("shell-action-1", "LOC_VICTORY_NAV_HELP_INSPECT");
		hotkeyContext.registerNavtray("shell-action-3", "LOC_VICTORY_NAV_HELP_RULES");
		model.tabNavStartup(hotkeyContext);
	});

	onCleanup(() => {
		hotkeyContext.unregisterNavtray("shell-action-1");
		hotkeyContext.unregisterNavtray("shell-action-3");
		model.tabNavShutdown(hotkeyContext);
	});

	return (
		<VictoryTabBase
			header={model.data.militaryDetails.headerText}
			titleColorClass={model.data.panels[2].titleColor}
			background={model.data.panels[2].background}
			targetScore={model.data.militaryDetails.targetScore}
			title="LOC_VICTORY_MILITARY_MODERN_NAME"
			rules="LOC_VICTORIES_RULES_MILITARY"
			pointsNeededText="LOC_DOMINION_POINTS_NEEDED_TO_WIN"
			preScrollContent={
				<VictoryHeader>
					<div class="size-full flex flex-row">
						<div class="w-full self-center">
							<div class="ml-2 uppercase fxs-header">
								<L10n.Compose text="LOC_GENERIC_SETTLEMENTS" />
							</div>
						</div>
					</div>
				</VictoryHeader>
			}
		>
			<VSlot
				class="victories-military-content victories-military-focus transition-opacity duration-150 ease-out w-full"
				lockNavigation={true}
				autoFocus={!model.tooltipToggle}
			>
				<For each={model.data.militaryDetails.playerDetails}>
					{(player, index) => (
						<VictoryRow
							rowId={index() + 1}
							playerInfo={player.playerInfo}
							divider={true}
							rowType={VictoryTabType.Military}
							showTooltip={false}
							activateInfo={(playerId: PlayerId) => {
								if (ActionHandler.isTouchActive) {
									model.focusPlayer(playerId, VictoryTabType.Military);
									model.onGamepadInspectButton();
								}
							}}
						>
							<div class="self-center flex flex-row flex-wrap">
								<For each={player.structures}>
									{(structure) => (
										<MilitaryTooltip {...structure}>
											<Activatable
												class={`victories-military-item-icon-outer relative ${layoutModel.screenWidthDownScaled() < 1784 ? "size-8" : "size-16"}`}
												onFocus={() => onMilitaryFocus(player.playerInfo.playerId)}
												onBlur={() => onMilitaryBlur(player.playerInfo.playerId)}
											>
												<Show when={player.playerInfo.highlighted()}>
													<div class="victories-military-item-icon font-body text-lg text-body self-center">
														{structure.points.toString()}
													</div>
												</Show>
												<div
													class={`absolute inset-0 victories-structure-icon bg-contain bg-no-repeat ${structure.iconClass} ${player.playerInfo.highlighted() ? "opacity-20" : "opacity-70"}`}
													style={{
														"background-image": structure.iconURL,
														// eslint-disable-next-line solid/style-prop
														"fxs-background-image-tint": `${structure.wasConqueredFromIdeologicalOpponent ? RIVAL_IDEOLOGY_TINT : SAME_IDEOLOGY_TINT}`,
													}}
												/>
											</Activatable>
										</MilitaryTooltip>
									)}
								</For>
							</div>
						</VictoryRow>
					)}
				</For>
			</VSlot>
		</VictoryTabBase>
	);
};
